use std::collections::HashMap;

fn apply_remove_cargo_dependency (details : & RemoveCargoDependencyDetails) -> Result < () > { eprintln ! ("  Removing dependency '{}' from Cargo.toml: {:?}" , details . package_name , details . target_file) ; let content = fs :: read_to_string (& details . target_file) . with_context (| | format ! ("Failed to read Cargo.toml: {:?}" , details . target_file)) ? ; let mut doc = content . parse :: < DocumentMut > () . with_context (| | format ! ("Failed to parse Cargo.toml: {:?}" , details . target_file)) ? ; let mut changed = false ; let root_table = doc . as_table_mut () ; let mut remove_from_table_section = | table : & mut toml_edit :: Table , section_key : & str , package_name : & str | { if let Some (item) = table . get_mut (section_key) { if let Some (sub_table) = item . as_table_mut () { if sub_table . contains_key (package_name) { sub_table . remove (package_name) ; eprintln ! ("    Removed '{}' from [{}]" , package_name , section_key) ; true } else { false } } else { false } } else { false } } ; changed |= remove_from_table_section (root_table , "dependencies" , & details . package_name) ; changed |= remove_from_table_section (root_table , "dev-dependencies" , & details . package_name) ; changed |= remove_from_table_section (root_table , "build-dependencies" , & details . package_name) ; if let Some (workspace_item) = root_table . get_mut ("workspace") { if let Some (workspace_table) = workspace_item . as_table_mut () { changed |= remove_from_table_section (workspace_table , "dependencies" , & details . package_name) ; } } if let Some (patch_item) = root_table . get_mut ("patch.crates-io") { if let Some (patch_table) = patch_item . as_table_mut () { changed |= remove_from_table_section (patch_table , "patch.crates-io" , & details . package_name) ; } } if let Some (workspace_item) = root_table . get_mut ("workspace") { if let Some (workspace_table) = workspace_item . as_table_mut () { if let Some (members_item) = workspace_table . get_mut ("members") { if let Some (members_array) = members_item . as_array_mut () { let initial_len = members_array . len () ; members_array . retain (| item | { item . as_str () . map_or (true , | s | s != details . package_name) }) ; if members_array . len () < initial_len { eprintln ! ("    Removed '{}' from [workspace.members]" , details . package_name) ; changed = true ; } } } } } if changed { fs :: write (& details . target_file , doc . to_string () . as_bytes ()) . with_context (| | format ! ("Failed to write modified Cargo.toml: {:?}" , details . target_file)) ? ; eprintln ! ("  Successfully removed dependency '{}' from {:?}" , details . package_name , details . target_file) ; } else { eprintln ! ("  Dependency '{}' not found in any relevant section of {:?}" , details . package_name , details . target_file) ; } Ok (()) }